#include <iostream>
#include <cmath>

int main() {
    int h, n;
    std::cin >> h >> n;
    n = n - 1 + (1 << h);
    int result = h;
    for (int i = 1; i <= h; ++i) {
        int bit_i = n & (1 << i);
        int bit_prev = n & (1 << (i - 1));
        if (!(((bit_i == 0) ? 0 : 1) ^ ((bit_prev == 0) ? 0 : 1))) {
            result += (1 << i) - 1;
        }
    }
    std::cout << result << std::endl;
    return 0;
}
